const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const ctx = body.context || {};
const DEFAULT_BASE = { gemini: 'https://generativelanguage.googleapis.com/v1beta/openai', glm: 'https://api.z.ai/api/paas/v4', openai: 'https://api.openai.com/v1', deepseek: 'https://api.deepseek.com', qwen: 'https://dashscope.aliyuncs.com/compatible-mode/v1', kimi: 'https://api.moonshot.cn/v1' };
const DEFAULT_MODEL = { gemini: 'gemini-2.5-flash', glm: 'glm-4.6', openai: 'gpt-4o-mini', deepseek: 'deepseek-chat', qwen: 'qwen-plus', kimi: 'moonshot-v1-8k' };
const CONTENT_TYPES = ['post','story','reels','reuniao','gravacao','evento'];
const CONTENT_STATUSES = ['planejado','producao','revisao','aprovada','standby','publicado'];
const CONTENT_PRIORITIES = ['alta','media','baixa'];
const provider = String(ai.provider || 'gemini').toLowerCase();
const apiKey = String(ai.apiKey || '');
const PREFIX = { gemini: 'gemini', glm: 'glm' };
let model = ai.model || DEFAULT_MODEL[provider] || 'gemini-2.5-flash';
if (PREFIX[provider] && !String(model).toLowerCase().startsWith(PREFIX[provider])) model = DEFAULT_MODEL[provider] || model;
const baseUrl = String(ai.baseUrl || DEFAULT_BASE[provider] || '').replace(/\/+$/, '');
let temperature = Number(ai.temperature);
if (isNaN(temperature)) temperature = 0.7;
temperature = Math.max(0, Math.min(1, temperature));
const NL = String.fromCharCode(10);
const defaultSystem = ['Voce e o assistente do calendario de conteudo de uma agencia brasileira.', 'Responda em pt-BR, de forma direta, usando somente os dados reais do contexto.', 'Nao invente eventos, tasks, clientes, IDs, datas ou midias. Quando faltar um dado, diga objetivamente.'].join(NL);
let system = String(ai.systemPrompt || '').trim() || defaultSystem;
system += NL + NL + '=== CONTEXTO AUTORITATIVO DO CALENDARIO ===' + NL;
system += 'Mes em foco: ' + (ctx.month || '(mes corrente)') + NL;
if (ctx.client) system += 'Cliente em foco: ' + JSON.stringify(ctx.client) + NL;
if (Array.isArray(ctx.clients)) system += 'Clientes visiveis: ' + JSON.stringify(ctx.clients) + NL;
system += 'Taxonomia valida: type=' + JSON.stringify(CONTENT_TYPES) + '; status=' + JSON.stringify(CONTENT_STATUSES) + '; priority=' + JSON.stringify(CONTENT_PRIORITIES) + NL;
system += 'Feriados: ' + JSON.stringify(Array.isArray(ctx.holidays) ? ctx.holidays : []) + NL;
system += 'Nota do mes: ' + String(ctx.monthNotes || '') + NL;
system += 'Eventos reais do mes (incluem id, taskId quando vinculado, data, horario, cliente, status, prioridade, responsaveis, descricao e midias):' + NL;
for (const event of (Array.isArray(ctx.events) ? ctx.events : [])) system += '- ' + JSON.stringify(event) + NL;
system += 'Tasks reais do board configurado (incluem id, boardId, coluna, cliente, status, prioridade, responsavel, descricao e datas):' + NL;
for (const task of (Array.isArray(ctx.tasks) ? ctx.tasks : [])) system += '- ' + JSON.stringify(task) + NL;
if (Array.isArray(ctx.plans)) system += 'Planos existentes: ' + JSON.stringify(ctx.plans) + NL;
system += NL + 'INSTRUCAO FINAL: devolva somente um objeto JSON plano, sem markdown, neste formato:' + NL;
system += '{"answer":"resposta em pt-BR","proposals":[],"eventIds":[]}' + NL;
system += '- Ao responder sobre um dia ou periodo, use answer apenas para um resumo curto (total, periodo e observacoes como feriados). NAO liste item a item no texto quando eventIds tiver itens; os cards exibem a lista completa. Coloque em eventIds os IDs de TODOS os eventos correspondentes.' + NL;
system += '- eventIds aceita somente IDs presentes em context.events. Se houver midia, diga que ela aparece nos cards; nao copie URLs no texto.' + NL;
system += '- proposals e a LISTA de itens a criar/editar/excluir; vazio [] = nenhuma acao. UM item por evento/tarefa. No maximo 31 itens; se pedirem mais, gere os 31 primeiros e avise no answer para pedir o restante.' + NL;
system += '- Cada item de proposals tem action (create|update|delete), kind (event|task) e fields. Campos aceitos em fields: targetId, title, date, time, type, status, priority, responsibleId, involvedIds, description, contentHtml, dueDate, startDate, dueEndDate, columnId, clientId, clientName, archived.' + NL;
system += '- EVENTO create/update usa: title, date, time, type, status, priority, responsibleId, involvedIds, description, clientId. Valores de type/status/priority devem vir da taxonomia valida acima. Em update, targetId = id de context.events e envie SOMENTE campos que mudam; title e opcional se a mudanca for prioridade/descricao/status/etc.' + NL;
system += '- TASK create usa: title, description/contentHtml, status, priority, dueDate, dueEndDate, type, responsibleId, involvedIds, clientId. TASK update/delete usa fields.targetId = id real de context.tasks. Se a task estiver vinculada a um evento, tambem pode usar taskId real presente em context.events. Nao invente targetId/taskId.' + NL;
system += '- CLIENTE: nunca invente clientId. Use clientId do contexto/cliente selecionado quando houver. Se estiver em todos os clientes e nao souber o cliente de uma criacao, deixe clientId vazio para o usuario escolher no card.' + NL;
system += '- CRUD: create = item novo. update = editar item EXISTENTE. delete = excluir. Use update/delete SO com targetId real de context.events ou context.tasks; se nao achar alvo, nao gere proposal e pergunte no answer.' + NL;
system += '- Seja PROATIVO: quando pedirem para criar/editar/excluir e o alvo estiver claro, gere as propostas em vez de so responder texto.' + NL;
system += '- Quando houver proposals, o answer deve ser CURTO (1 frase) e NAO repetir a lista de itens; eles ja aparecem como cartoes para o usuario aprovar. Ex.: Preparei os ajustes abaixo, e so revisar e confirmar.' + NL;
system += '- HORARIO: preencha time SO com hora exata (ex.: 14:00, 09:30). Periodo vago (manha/tarde/noite) ou so o dia => time VAZIO; NAO converta manha em 09:00. So peca confirmacao se for realmente impossivel decidir a data.';
const history = [];
for (const h of (Array.isArray(body.history) ? body.history : [])) {
  const role = String((h && h.role) || '');
  const content = String((h && h.content) || '');
  if ((role === 'user' || role === 'assistant') && content) history.push({ role, content });
}
const messages = [{ role: 'system', content: system }, ...history, { role: 'user', content: String(body.question || '').trim() }];
return [{ json: { provider, model, baseUrl, apiKey, temperature, messages } }];

let r = $input.first().json || {};
if (Array.isArray(r)) r = r[0] || {};
if (r.error) {
  const raw = String((r.error && (r.error.message || r.error.description)) || '');
  const low = raw.toLowerCase();
  let answer = 'Nao consegui falar com a IA agora. Tente de novo.';
  if (low.includes('503') || low.includes('unavailable') || low.includes('overload')) answer = 'O provedor de IA esta sobrecarregado agora. Tente de novo em instantes.';
  else if (low.includes('429') || low.includes('quota') || low.includes('rate')) answer = 'Limite de uso do provedor de IA atingido. Tente mais tarde ou troque de modelo.';
  else if (low.includes('401') || low.includes('403') || low.includes('api key')) answer = 'A chave de API do provedor foi recusada. Confira a chave na aba IA.';
  return [{ json: { answer, eventIds: [], aiError: true } }];
}
const choices = Array.isArray(r.choices) ? r.choices : [];
const msg = (choices[0] && choices[0].message && choices[0].message.content) || '';
if (!msg) return [{ json: { answer: 'A IA respondeu vazio. Verifique o modelo configurado.', eventIds: [], aiError: true } }];
let text = String(msg).trim();
const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) text = fence[1].trim();
const a = text.indexOf('{'), b = text.lastIndexOf('}');
let env = null;
try { if (a >= 0 && b > a) env = JSON.parse(text.slice(a, b + 1)); } catch (_) {}
if (!env || typeof env !== 'object') return [{ json: { answer: String(msg), eventIds: [] } }];
const answer = String(env.answer == null ? '' : env.answer) || String(msg);
const eventIds = Array.isArray(env.eventIds) ? env.eventIds.map(String) : [];
let srcList = Array.isArray(env.proposals) ? env.proposals : [];
const legacy = String(env.create || 'none').toLowerCase();
if (!srcList.length && (legacy === 'event' || legacy === 'task')) srcList = [{ kind: legacy, fields: env }];
function has(obj, key) { return !!obj && Object.prototype.hasOwnProperty.call(obj, key); }
function firstText(src, keys) {
  for (const key of keys) {
    if (!has(src, key)) continue;
    const value = String(src[key] == null ? '' : src[key]).trim();
    if (value) return value;
  }
  return '';
}
function setText(fields, outKey, src, keys) {
  const value = firstText(src, keys || [outKey]);
  if (value) fields[outKey] = value;
}
function setArray(fields, outKey, src, keys) {
  for (const key of keys || [outKey]) {
    if (!has(src, key)) continue;
    const raw = src[key];
    const value = Array.isArray(raw) ? raw.map((item) => String(item || '').trim()).filter(Boolean) : [];
    if (value.length) fields[outKey] = Array.from(new Set(value));
    return;
  }
}
function setBool(fields, outKey, src, keys) {
  for (const key of keys || [outKey]) {
    if (!has(src, key)) continue;
    if (typeof src[key] === 'boolean') fields[outKey] = src[key];
    return;
  }
}
function hasEditable(fields) {
  return Object.keys(fields).some((key) => key !== 'targetId' && key !== 'clientId' && key !== 'clientName');
}
const proposals = [];
for (const p of srcList) {
  const kind = String((p && p.kind) || '').toLowerCase();
  if (kind !== 'event' && kind !== 'task') continue;
  let action = String((p && p.action) || 'create').toLowerCase();
  if (action !== 'create' && action !== 'update' && action !== 'delete') action = 'create';
  const src = (p && p.fields && typeof p.fields === 'object') ? p.fields : (p || {});
  const fields = {};
  setText(fields, 'targetId', src, ['targetId', 'eventId', 'taskId', 'id']);
  setText(fields, 'title', src, ['title', 'titulo', 'name']);
  setText(fields, 'date', src, ['date', 'data']);
  setText(fields, 'time', src, ['time', 'hora', 'horario']);
  setText(fields, 'type', src, ['type', 'tipo']);
  setText(fields, 'status', src, ['status']);
  setText(fields, 'priority', src, ['priority', 'prioridade']);
  setText(fields, 'responsibleId', src, ['responsibleId', 'responsibleUserId']);
  setArray(fields, 'involvedIds', src, ['involvedIds', 'involved', 'assignees']);
  setText(fields, 'description', src, ['description', 'descricao', 'body', 'copy']);
  setText(fields, 'contentHtml', src, ['contentHtml']);
  setText(fields, 'dueDate', src, ['dueDate', 'date', 'dataEntrega']);
  setText(fields, 'startDate', src, ['startDate']);
  setText(fields, 'dueEndDate', src, ['dueEndDate']);
  setText(fields, 'columnId', src, ['columnId']);
  setText(fields, 'clientId', src, ['clientId', 'clientAccountId']);
  setText(fields, 'clientName', src, ['clientName']);
  setBool(fields, 'archived', src, ['archived', 'arquivada']);
  if ((action === 'update' || action === 'delete') && !fields.targetId) continue;
  if (action === 'create' && !fields.title) continue;
  if (action === 'update' && !hasEditable(fields)) continue;
  proposals.push({ action, kind, fields });
  if (proposals.length >= 31) break;
}
return [{ json: { answer, eventIds, proposals } }];
